@page "/dashboard"
@rendermode InteractiveServer
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@inject InventoryAlertState AlertState
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Current Warehouse</h5>
                <p class="card-text fs-4">
                    @GetWarehouseName(WarehouseState.SelectedWarehouseId)
                </p>
            </div>
        </div>
    </div>
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="card-text">
                    @if (AlertState.LowStockCount > 0)
                    {
                        <span class="text-danger fs-4">
                            ⚠️ @AlertState.LowStockCount items below minimum levels
                        </span>
                    }
                    else
                    {
                        <span class="text-success fs-4">
                            ✅ All items adequately stocked
                        </span>
                    }
                </p>
                <small class="text-muted">Refreshes every 10 seconds</small>
            </div>
        </div>
    </div>
</div>

@code {
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override void OnInitialized()
    {
        _warehouseHandler = () => InvokeAsync(OnWarehouseChanged);
        _alertHandler = () => InvokeAsync(StateHasChanged);

        WarehouseState.OnChange += _warehouseHandler;
        AlertState.OnChange += _alertHandler;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await PollNow();
            StartPolling();
        }
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken token)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(token))
            {
                await PollNow();
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on dispose
        }
    }

    private async Task PollNow()
    {
        var count = await AlertService.GetLowStockCountAsync(WarehouseState.SelectedWarehouseId);
        // Updating via the shared state notifies ALL subscribers (sidebar badge, this page, etc.)
        AlertState.UpdateCount(count);
    }

    private async Task OnWarehouseChanged()
    {
        // When warehouse changes, immediately refresh alerts for the new warehouse
        await PollNow();
        StateHasChanged();
    }

    private static string GetWarehouseName(string id) =>
        WarehouseState.AvailableWarehouses.FirstOrDefault(w => w.Id == id).Name ?? id;

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();

        if (_warehouseHandler is not null)
            WarehouseState.OnChange -= _warehouseHandler;
        if (_alertHandler is not null)
            AlertState.OnChange -= _alertHandler;
    }
}

